export default function ContactForm() {
  // Inline Server Action: 'use server' at the top of the function body marks it
  // as a Server Function. This works because ContactForm is a Server Component.
  async function submitContactMessage(formData: FormData) {
    'use server'

    const name = formData.get('name')
    const email = formData.get('email')
    const message = formData.get('message')

    // Validate on the server too — FormData is untrusted, and actions are
    // reachable via direct POST requests, not just through this form.
    const missing = Object.entries({ name, email, message })
      .filter(([, value]) => typeof value !== 'string' || value.trim() === '')
      .map(([field]) => field)

    // Expected errors are modelled as return values rather than thrown.
    if (missing.length > 0) {
      return {
        message: `Please fill in all fields: ${missing.join(', ')}`,
      }
    }

    // Simulate saving the contact message
    console.log('Saving contact message:', {
      name: (name as string).trim(),
      email: (email as string).trim(),
      message: (message as string).trim(),
    })

    return { message: 'Thanks! Your message has been sent.' }
  }

  return (
    <div>
      <h2>Contact Us</h2>

      <form action={submitContactMessage}>
        <label htmlFor="contact-name">Name</label>
        <input id="contact-name" name="name" placeholder="Name" required />

        <label htmlFor="contact-email">Email</label>
        <input
          id="contact-email"
          name="email"
          type="email"
          placeholder="Email"
          required
        />

        <label htmlFor="contact-message">Message</label>
        <textarea
          id="contact-message"
          name="message"
          rows={5}
          placeholder="Message"
          required
        />

        <button type="submit">Send Message</button>
      </form>
    </div>
  )
}

